beforeExample:
import org.eclipse.swt.SWT;
import org.eclipse.swt.widgets.FileDialog;
import org.eclipse.swt.widgets.Shell;

public class TestClass {
    public void configureFilters(Shell shell) {
        FileDialog fileDialog = new FileDialog(shell, SWT.SAVE | SWT.SHEET);
        fileDialog.setFilterExtensions(new String[] { "*.csv" });
        fileDialog.setFilterNames(new String[] { "CSV Files" });
    }

    public void anotherMethod(String someFilter) {
        // This case should also match, with a variable instead of a literal
        configureFilters(new Shell());
        new FileDialog(new Shell()).setFilterExtensions(new String[] { someFilter });
    }
}

